import {
  index,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  serial,
  text,
  timestamp,
  uuid,
} from "drizzle-orm/pg-core";

const ts = (name: string) => timestamp(name, { withTimezone: true, mode: "date" });

export const ingestionRuns = pgTable(
  "ingestion_runs",
  {
    /** UUIDv7, generated by the caller (see uuidv7 in @bondcheck/shared) */
    id: uuid("id").primaryKey(),
    job: text("job").notNull(),
    /** 'vercel-cron' | 'gha' | 'cli' | 'cf-cron' | 'manual' */
    trigger: text("trigger").notNull(),
    startedAt: ts("started_at").notNull(),
    finishedAt: ts("finished_at"),
    /** 'running' | 'ok' | 'partial' | 'failed' */
    status: text("status").notNull(),
    /** resume point for chunked jobs */
    cursor: jsonb("cursor"),
    stats: jsonb("stats"),
    error: text("error"),
  },
  (t) => [index("idx_runs_job_started").on(t.job, t.startedAt)],
);

export const ingestionIssues = pgTable(
  "ingestion_issues",
  {
    id: serial("id").primaryKey(),
    runId: uuid("run_id")
      .notNull()
      .references(() => ingestionRuns.id, { onDelete: "cascade" }),
    /** 'info' | 'warn' | 'error' */
    severity: text("severity").notNull(),
    entity: text("entity").notNull(),
    entityKey: text("entity_key").notNull(),
    message: text("message").notNull(),
    details: jsonb("details"),
    createdAt: ts("created_at").defaultNow(),
    resolvedAt: ts("resolved_at"),
  },
  (t) => [index("idx_issues_run").on(t.runId)],
);

export const rateLimits = pgTable(
  "rate_limits",
  {
    key: text("key").notNull(),
    windowStart: ts("window_start").notNull(),
    count: integer("count").notNull().default(0),
  },
  (t) => [primaryKey({ columns: [t.key, t.windowStart] })],
);
